$events = Get-WinEvent -FilterHashtable @{LogName="Microsoft-Windows-TerminalServices-LocalSessionManager/Operational"; ID=21; StartTime=(Get-Date).AddDays(-30)} && Write-Host "Found" $events.length "connections between" @(Get-Date -UFormat %D) "and" @(@(Get-Date).AddDays(-30).ToString('MM/dd/yy')) && Format-Table -InputObject $events -Wrap -PropertyMessage -Autosize | Out-File -FilePath "C:\INS-Temp\RDPLog\RDPLog_$(Get-Date -UFormat %m_%d_%Y).txt"